window.__posterData({"id": "klara-johansson", "name": "Klara Johansson", "folder": "week3_poster_Klara_Johansson", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Jag har kommenterat på de delarna jag förstår i koden med vanliga kommentarer och sedan markerat med: (AI kommentar) på de kommentarer som AI lade till i koden\n// Har även skrivit kommentarer under delar jag inte förstår\n// För att hitta i koden står det (STEG 1), (STEG 2) eller (STEG 3)\n// Jag har skrivit det mesta av mina reflektioner ovanför koden\n\n// STEG 1 reflektion\n// Jag bad AI:n skriva om min ursprungliga kod utan att ändra hur postern ser ut eller beter sig. Utseendet och beteendet på postern var likadant när jag körde koden dock var det mycket fler rader kod jämfört med min egen. Koden gick från 109 rader till ca 300. Jag har även haft svårare att hitta i den nya koden då det är en struktur jag själv inte är van vid och många nya tillagda variabler.\n\n// Det som jag har förtsått att AI:n gjorde i omskrivningen av koden var att den delade upp draw() i små funktioner: drawImages(), drawPosterText(), drawClickHint(), drawDrunkEffect() och drawStars().\n// Den lade även till otroligt många konstanter vilket jag tyckte var lite onödigt för att man kan lägga ihop relaterade kosntanter till en kodsnutt istället för att dela upp dem. Men samtidigt gör konstanterna det lättare att hitta i koden och göra små justeringar.\n// AI:n la även postertexten och stjärnornas positioner i arrays med objekt tex. const POSTER_TEXT = [\"KLARA\", \"JOHANSSON\", \"16TH OCT 26\"];. Arrays är bra då man slipper skriva samma kod flera gånger. Detta är något jag vill bli bättre på för att få en mer strukturerad kod.\n// Det sista som AI:n ändrade på var att den bytte namn på mina gamla variabler (txt blev drunkMode, Background blev backgroundImg) \n\n// STEG 2 reflektion\n// Här bad jag AI:n ändra något specifikt (för att hitta se kommentarerna \"STEG 2\" i koden, där reflekterar jag även om min förståelse för ändringarna).\n// Efter poster-uppgiften var jag inte helt nöjd med min poster. Jag kände att det var för lite som hände och jag fick även kritik på att jag borde göra så att texten rör sig. Därför tog jag nu tillfället i akt och bad AI:n att förändra alla texter så att de rörde på sig. Jag skrev att texten \"KLARA JOHANSSON 16TH OCT 26\" och \"click to partayyy\" skulle blinka på ett techno-aktigt sätt utan att dra åt sig för mycket uppmärksamhet. Jag valde sedan att själv ändra på textens position och storlek för att det skulle se bättre ut och passa in i nya canvas storleken som vi behövde ha. Jag bad den även att ändra Techno.png och rave.png så att den rörde sig \"coolt\" och att den pulserar i storlek.\n// Jag gillade dessa ändringar då texterna fortfarande var läsbara men gjorde postern mer intressant att kolla på. Något jag gillar mindre med bild animationen är att den känns lite för liten och placeringen är lite för högt upp efter att AI:n lade till animationen. Det hade även varit coolt om texterna glitchade i olika färger men valde att inte förändra det då jag tror att det hade blivit lite för många intryck.\n\n// AI:n använde sig av push()/pop() med translate() och imageMode(CENTER), vilket är helt nytt för mig och jag lärde mig att dessa gör att bilderna växer från mitten istället för från hörnet.\n\n// STEG 3 reflektion\n// Jag bad AI:n att föreslå en egen funktion utan att ge vägledning (för att hitta se kommentarerna \"DEL 3\" i koden). Den valde att animera trippy pulserande ringar bakom techno- och rave-bilderna. Dessa ringar expanderar från mitten i 128 BPM, skiftar färg och följer musen.\n// Jag tycker att färgerna passar in i postern och rave-temat och att ringarna följer musen gör affischen mer interaktiv och spännande. Jag tycker dock att det plötsligt blev lite för mycket som rörde sig och ringarna tog uppmärksamheten från texten. Jag valde därför att sänka RING_ALPHA till 30 och öka RING_COUNT och RING_WOBBLE. Vilket gjorde det lite mer flytande och diskret.\n// Något som var nytt för mig var bland annat HSB-färgläge, millis() för att räkna beat, lerp() för mjuk rörelse mot musen, och beginShape() med vertex() för att rita en bölgande ring. Jag förstår idén men inte alls alla matteformler och hur allt hänger ihop.\n// Jag testade även att ändra att ringarna skulle följa efter musen mer exakt för att se hur det skulle se ut men ändrade tillbaka då det inte gav samma \"trippy\" känsla med att allt är lite fördröjt.\n\n\n// ---------- Konstanter ---------- (AI kommentar)\nconst CANVAS_W = 600; // Storleken på canvasen\nconst CANVAS_H = 800; // Storleken på canvasen\n\nconst BLUE = [0, 0, 255];\nconst DRUNK_TEXT = \"GET DRUNK\";\n\n// Text\nconst POSTER_TEXT_SIZE = 28;  // text storlek\nconst POSTER_MARGIN = 30;     // avstånd till canvasens kant\nconst POSTER_LINE_HEIGHT = 38;\nconst POSTER_TEXT = [\"KLARA\", \"JOHANSSON\", \"18TH NOV 26\"];\n\n// STEG 2: inställningar för blinkandet\nconst POSTER_GLITCH_PERIOD = 45; // en rad glitchar var 45:e bildruta\nconst POSTER_GLITCH_FRAMES = 3;  // hur många bildrutor glitchen varar\n// STEG 2: inställningar för blinkandet på \"click to partayyy\"\nconst CLICK_GLITCH_PERIOD = 45; // glitchar var 45:e bildruta\nconst CLICK_GLITCH_FRAMES = 3;  // hur många bildrutor glitchen varar\nconst CLICK_GLITCH_OFFSET = 22; // förskjutning så att den inte glitchar samtidigt som postertexten\n\n// Stjärnor\nconst STARS = [\n  { x: 94,  y: 785 }, \n  { x: 550, y: 296 }, \n];\nconst STAR_INNER_RADIUS = 75;  \nconst STAR_OUTER_RADIUS = 150; \nconst STAR_POINTS = 5;\nconst STAR_INTERVAL = 10; // stjärnorna ritas var tionde bildruta\n\n// STEG 2: bildernas position, storlek och animationsinställningar\nconst IMG_SCALE = 1.5;                 // hur mycket större bilderna ritas än originalet\nconst TECHNO_POS = { x: 71,  y: 156 }; // övre vänstra hörnet i vila (var 45, 105)\nconst RAVE_POS   = { x: 157, y: 296 }; // övre vänstra hörnet i vila (var 100, 200)\nconst PULSE_SPEED = 0.08;     // hur snabbt bilderna pulserar\nconst PULSE_AMOUNT = 0.15;    // hur mycket större/mindre (0.15 = ±15 %)\nconst WOBBLE_AMOUNT = 0.08;   // hur mycket techno-bilden gungar (radianer)\nconst RAVE_BLINK_PERIOD = 40; // rave-bilden blinkar var 40:e bildruta\n\n// STEG 3: Vad AI:n ändrade\n// NY: trippy pulserande ringar\n// Mina egna ändringar efteråt: RING_COUNT 20, RING_MAX_RADIUS 300, RING_WOBBLE 50 och RING_ALPHA 30 för att göra animeringen mer diskret \nconst RING_COUNT = 20;         // antal ringar\nconst RING_BPM = 128;          // tempo, ringarna pulserar i takt\nconst RING_MAX_RADIUS = 300;   // hur långt ut ringarna går\nconst RING_WOBBLE = 50;        // hur mycket ringarna vibrerar/böljar\nconst RING_ALPHA = 30;         // styrka (0-100), lägre = mer diskret\nlet ringCenter = { x: CANVAS_W / 2, y: CANVAS_H * 0.45 }; // ringarnas mittpunkt\nlet ringBoost = 0;             // extra kick vid klick\n\n// ---------- Tillstånd ---------- (AI kommentar)\nlet backgroundImg, technoImg, raveImg;\nlet drunkMode = false; // true = GET DRUNK-effekten är på\n\n// ---------- Setup ---------- (AI kommentar)\nasync function setup() {\n  createCanvas(CANVAS_W, CANVAS_H);\n  // background(0) borttagen (svart bakgrund)\n  textFont(\"Helvetica\");\n\n  // Promise.all väntar tills samtliga bilder har laddats\n  [backgroundImg, technoImg, raveImg] = await Promise.all([\n    loadImage(\"background.png\"),\n    loadImage(\"techno.png\"),\n    loadImage(\"rave.png\"),\n  ]);\n}\n\n// ---------- Draw ---------- (AI kommentar)\nfunction draw() {\n  // STEG 2: vänta tills bilderna har laddats (animationen behöver bildernas storlek)\n  if (!backgroundImg || !technoImg || !raveImg) return;\n\n  drawImages();\n  drawPosterText();\n\n  if (drunkMode) {\n    drawDrunkEffect();\n  } else {\n    drawClickHint();\n  }\n\n  if (frameCount % STAR_INTERVAL === 0) {\n    drawStars();\n  }\n}\n\n// STEG 3: Vad AI:n ändrade\n// AI:n bytte ut min drawImages() mot den här. Det enda nya är raden drawTrippyRings(), som ritas efter bakgrunden men före techno och rave, så att ringarna hamnar bakom bilderna.\nfunction drawImages() {\n  image(backgroundImg, 0, 0, width, height); // ÄNDRAT (steg 2): sträcks över hela canvasen\n  drawTrippyRings(); // Steg 3: ringar bakom techno och rave\n  drawTechno();\n  drawRave();\n}\n\n// STEG 3: Vad AI:n ändrade\n// Trippy ringar som pulserar i takt med RING_BPM.\n// Färgen går runt hela färgskalan, ringarna böljar och mitten följer musen.\nfunction drawTrippyRings() {\n  // Mål för mitten: canvasens mitt, dragen halvvägs mot musen om den är på canvasen\n  let targetX = width / 2;\n  let targetY = height * 0.45;\n  if (mouseX > 0 && mouseX < width && mouseY > 0 && mouseY < height) {\n    targetX = lerp(targetX, mouseX, 0.5);\n    targetY = lerp(targetY, mouseY, 0.5);\n  }\n  ringCenter.x = lerp(ringCenter.x, targetX, 0.08); // glider mjukt\n  ringCenter.y = lerp(ringCenter.y, targetY, 0.08);\n\n  // Takten: beat går upp ett steg per slag, kick är en snabb puls i början av varje slag (AI kommentar)\n  const beat = millis() / (60000 / RING_BPM);\n  ringBoost *= 0.92; // klickets extra kick klingar av\n  const kick = min(1, pow(1 - (beat % 1), 4) + ringBoost);\n\n  push();\n  colorMode(HSB, 360, 100, 100, 100);\n  noFill();\n\n  for (let i = 0; i < RING_COUNT; i++) {\n    // p går från 0 (mitten) till 1 (ytterkanten) och börjar sedan om (AI kommentar)\n    // Detta förstår jag inte alls \n    const p = (beat * 0.25 + i / RING_COUNT) % 1;\n    const fade = 1 - p;\n    const r = p * RING_MAX_RADIUS * (1 + 0.04 * kick);\n    const hue = (frameCount * 0.6 + i * 40) % 360;\n\n    stroke(hue, 80, 100, RING_ALPHA * fade);\n    strokeWeight(2 + 10 * fade + 6 * kick * fade);\n\n    // Förstår inte detta förutom att detta är formen på cirklarna\n    // Ritas som en polygon med sinus-störning så att ringen böljar (AI kommentar)\n    beginShape();\n    for (let a = 0; a < TWO_PI; a += 0.1) {\n      const wob = sin(a * 6 + frameCount * 0.05 + i) * RING_WOBBLE * p;\n      vertex(\n        ringCenter.x + cos(a) * (r + wob),\n        ringCenter.y + sin(a) * (r + wob)\n      );\n    }\n    endShape(CLOSE);\n  }\n  pop();\n}\n\n// STEG 2: techno-bilden pulserar (större/mindre) och gungar fram och tillbaka\nfunction drawTechno() {\n  const t = frameCount * PULSE_SPEED;\n  const s = IMG_SCALE * (1 + PULSE_AMOUNT * sin(t));\n  const angle = WOBBLE_AMOUNT * sin(t * 0.5);\n\n  // Mittpunkten i vila, så att bilden växer och krymper utåt från mitten (AI kommentar)\n  const cx = TECHNO_POS.x + (technoImg.width * IMG_SCALE) / 2;\n  const cy = TECHNO_POS.y + (technoImg.height * IMG_SCALE) / 2;\n\n  push();\n  translate(cx, cy);\n  rotate(angle);\n  imageMode(CENTER);\n  image(technoImg, 0, 0, technoImg.width * s, technoImg.height * s);\n  pop();\n}\n\n// STEG 2: rave-bilden pulserar i motfas mot techno-bilden och blinkar med färgblixtar\nfunction drawRave() {\n  const t = frameCount * PULSE_SPEED;\n  const s = IMG_SCALE * (1 - PULSE_AMOUNT * sin(t)); // motsatt rörelse mot techno (AI kommentar)\n\n  const cx = RAVE_POS.x + (raveImg.width * IMG_SCALE) / 2;\n  const cy = RAVE_POS.y + (raveImg.height * IMG_SCALE) / 2;\n\n  // De första bildrutorna i varje period blixtrar med slumpad färg,\n  // en kort stund därefter är bilden halvgenomskinlig (AI kommentar)\n  const phase = frameCount % RAVE_BLINK_PERIOD;\n\n  push();\n  if (phase < 4) {\n    tint(random(150, 255), random(150, 255), random(150, 255), 255); // färgblixt\n  } else if (phase < 8) {\n    tint(255, 90); // halvgenomskinlig\n  }\n  translate(cx, cy);\n  imageMode(CENTER);\n  image(raveImg, 0, 0, raveImg.width * s, raveImg.height * s);\n  pop();\n}\n\n// STEG 2: högerjusterad text nere i hörnet med en diskret techno-glitch.\n// Texten pulserar svagt i blå hela tiden. Var 45:e bildruta glitchar en rad i taget (uppifrån och ned) i 3 bildrutor vilket gör att den blir halvgenomskinlig\n// Pixlar hoppar i sidled och får en magenta \"spökkopia\" (AI kommentar) som jag ej föstår.\nfunction drawPosterText() {\n  push();\n  textSize(POSTER_TEXT_SIZE);\n  textAlign(RIGHT, BASELINE);\n  strokeWeight(8);\n\n  const right = width - POSTER_MARGIN;\n  const lastY = height - POSTER_MARGIN - 6;\n  const n = POSTER_TEXT.length;\n\n  // Svag pulsering i färgen (0 till 1) AI kommentar\n  const pulse = (sin(frameCount * 0.05) + 1) / 2;\n\n  // Vilken rad som glitchar just nu och om glitchen är aktiv AI KOMMENTAR\n  // Förstår inte\n  const glitchLine = floor(frameCount / POSTER_GLITCH_PERIOD) % n;\n  const glitching = frameCount % POSTER_GLITCH_PERIOD < POSTER_GLITCH_FRAMES;\n  // Förstår ej\n  for (let i = 0; i < n; i++) {\n    const x = right;\n    const y = lastY - (n - 1 - i) * POSTER_LINE_HEIGHT;\n\n    if (glitching && i === glitchLine) {\n      const dx = random(-4, 4);\n      // Magenta spökkopia bakom (AI kommentar)\n      noStroke();\n      fill(255, 0, 200, 110);\n      text(POSTER_TEXT[i], x + dx + 3, y);\n      // Själva texten, halvgenomskinlig (AI kommentar)\n      stroke(0, 150);\n      fill(0, 60, 255, 170);\n      text(POSTER_TEXT[i], x + dx, y);\n    } else {\n      stroke(0);\n      fill(0, 60 * pulse, 255); // blå som skiftar svagt mot ljusare (AI kommentar)\n      text(POSTER_TEXT[i], x, y);\n    }\n  }\n  pop();\n}\n\n// STEG: samma techno-glitch som postertexten.\nfunction drawClickHint() {\n  push();\n  textSize(30);    \n  strokeWeight(14); \n\n  // Svag pulsering i färgen (0 till 1) (AI kommentar)\n  const pulse = (sin(frameCount * 0.05) + 1) / 2;\n\n  const glitching =\n    (frameCount + CLICK_GLITCH_OFFSET) % CLICK_GLITCH_PERIOD < CLICK_GLITCH_FRAMES;\n  // förstår vad detta skapar i helhet men inte siffrorna och vissa kod ord som exempelvis dx\n  if (glitching) {\n    const dx = random(-4, 4);\n    // Magenta spökkopia bakom (AI kommentar)\n    noStroke();\n    fill(255, 0, 200, 110);\n    text(\"click to partayyy\", 330 + dx + 3, 60, 260, 100);\n    // Själva texten, halvgenomskinlig (AI kommentar)\n    stroke(0, 150);\n    fill(0, 60, 255, 170);\n    text(\"click to partayyy\", 330 + dx, 60, 260, 100);\n  } else {\n    stroke(0);\n    fill(0, 60 * pulse, 255); // blå som skiftar svagt mot ljusare (AI kommentar)\n    text(\"click to partayyy\", 330, 60, 260, 100);\n  }\n  pop();\n}\n\n// GET DRUNK-effekten: Oförändrad logik från steg 1, förutom att jag tog bort den svarta bakgrunden och gjorde canvasen till 600x800.\nfunction drawDrunkEffect() {\n  fill(random(255), random(255), random(255));\n  textSize(random(1, 25));\n  text(DRUNK_TEXT, random(width), random(height));\n}\n\nfunction drawStars() {\n  stroke(\"black\");\n  strokeWeight(20);\n\n  for (const s of STARS) {\n    fill(random(255), random(255), random(255));\n    star(s.x, s.y, STAR_INNER_RADIUS, STAR_OUTER_RADIUS, STAR_POINTS);\n  }\n}\n\n// ---------- Stjärnans form ---------- (AI kommentar)\n// (Steg 1: AI:n skrev om den här med en enda loop i stället för två vertex-block.)\n// x, y       = stjärnans mittpunkt (AI kommentar)\n// radius1    = inre radie (dalarna mellan spetsarna) (AI kommentar)\n// radius2    = yttre radie (spetsarna) (AI kommentar)\n// npoints    = antal spetsar (AI kommentar)\nfunction star(x, y, radius1, radius2, npoints) {\n  const halfAngle = TWO_PI / npoints / 2;\n\n  beginShape();\n  for (let i = 0; i < npoints * 2; i++) {\n    const r = i % 2 === 0 ? radius2 : radius1; // växla mellan yttre och inre punkt (AI kommentar)\n    const a = i * halfAngle;\n    vertex(x + cos(a) * r, y + sin(a) * r);\n  }\n  endShape(CLOSE);\n}\n\n// ---------- Interaktion ---------- (AI kommentar)\n// Vid musklick slås GET DRUNK-effekten på/av\nfunction mouseClicked() {\n  console.log(\"Klickat\");\n  drunkMode = !drunkMode;\n  // DEL 3: Vad AI:n ändrade \n  ringBoost = 1; // NY (steg 3): ringarna får en extra kick vid klick\n}", "assets": {"techno.png": {"mime": "image/webp", "b64": ""}, "rave.png": {"mime": "image/webp", "b64": ""}, "background.png": {"mime": "image/webp", "b64": ""}}});
